using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ChaoticCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/ChaoticCustomDescription", order = 0)]
public class ChaoticCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		string arg = (battleAction as ChaoticAction).StartingEpicPercentage.ToString();
		return Smart.Format(rawLocalizedDescription, arg);
	}
}
